breach.segment:
// Customise: alert when jobs were pending in >= 90 one-minute samples and the queue never drained.
// job/num_in_flight publishes up to ~12 minutes late, so a 120-minute window holds ~108 visible minutes.
WHERE backlogged_minutes >= 90 AND drained_minutes == 0
| SORT backlogged_minutes DESC, peak_pending_jobs DESC
| LIMIT 50
